using DomainModel.Models; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DomainModel.Configurations; public class PaymentConfiguration:IEntityTypeConfiguration<Payment>{ public void Configure(EntityTypeBuilder<Payment>b){ b.HasKey(x=>x.PaymentID); b.Property(x=>x.Amount).HasPrecision(18,0); b.Property(x=>x.TrackingCode).HasMaxLength(80).IsRequired(); b.HasIndex(x=>x.TrackingCode).IsUnique(); b.HasIndex(x=>new{x.UserID,x.CreateDate}); b.HasIndex(x=>x.MembershipPlanID); b.HasOne(x=>x.User).WithMany(x=>x.Payments).HasForeignKey(x=>x.UserID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x=>x.MembershipPlan).WithMany(x=>x.Payments).HasForeignKey(x=>x.MembershipPlanID).OnDelete(DeleteBehavior.Restrict); }}